values ('dialog_fq_merid_055', 'fq_merid_055', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Seize majority market share in the Shattered Heart", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 10x Aethel Abyssal Reaver; Defeat 6x Void Reaver\n\nSimple. Profitable. Done.\n\nRewards: 5000 EXP · 2500 Currency · 1250 CRD · 1700 Reputation · Event Horizon Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 385)
