values ('dialog_fq_merid_081', 'fq_merid_081', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Associate! Just who I wanted to see. Apex Portfolio — The Hidden Aethelgardian City is the ultimate real estate asset", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Travel to HIDDEN_AETHELGARDIAN_CITY; Collect 3x Secure city property deeds.\n\nSimple. Profitable. Done.\n\nRewards: 8000 EXP · 4000 Currency · 2000 CRD · 2500 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 411)
