values ('dialog_fq_omni_005', 'fq_omni_005', 'npc_omnicorp_class_trainer', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Class Module Installation — Your performance metrics have exceeded OmniCorp''s baseline projections", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Speak with npc_omnicorp_class_trainer; Speak with class_change_screen; Defeat 3x Plateau Drone\n\nReport completion via standard channels.\n\nRewards: 400 EXP · 200 Currency · 150 Reputation · Wpn Steel Broadsword + Arm Iron Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 434)
