values ('dialog_fq_omni_006', 'fq_omni_006', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Extraction Zone Delta is OmniCorp''s primary resource harvesting site on Xylos", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Travel to EXTRACTION_ZONE_DELTA; Collect 2x Complete extraction zone assessment.\n\nReport completion via standard channels.\n\nRewards: 100 EXP · 60 Currency · 60 Reputation · Con Nutrient Ration", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 435)
