values ('dialog_fq_omni_011', 'fq_omni_011', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The Secure Mining Grid predates OmniCorp''s formal Xylos colonization", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Travel to SECURE_MINING_GRID; Collect 2x Catalog recoverable hardware.\n\nReport completion via standard channels.\n\nRewards: 280 EXP · 150 Currency · 150 Reputation · Con Minor Stim Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 439)
