values ('dialog_fq_omni_012', 'fq_omni_012', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. The Grid Sentinel Drones are running on patrol protocols written for a diff...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 5x Grid Sentinel Drone; Collect 2x Upload updated patrol data.\n\nReport completion via standard channels.\n\nRewards: 320 EXP · 170 Currency · 170 Reputation · Scrap Circuit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 440)
