values ('dialog_fq_omni_013', 'fq_omni_013', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The Grid Defenders were the previous operators'' frontline combat units", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 5x Grid Defender; Collect 1x Upload new combat algorithm.\n\nReport completion via standard channels.\n\nRewards: 360 EXP · 190 Currency · 200 Reputation · Neural Interface Socket", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 441)
