values ('dialog_fq_omni_028', 'fq_omni_028', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Aethel Behemoths contain unique biological power cells", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 2x Aethel Behemoth; Collect 1x Submit power cell analysis.\n\nReport completion via standard channels.\n\nRewards: 900 EXP · 520 Currency · 260 CRD · 520 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 456)
