values ('dialog_fq_omni_029', 'fq_omni_029', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Sentinel Reactivation — Titan Assembly Sentinels auto-reactivate every 72 hours", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 4x Titan Assembly Sentinel; Collect 1x Confirm permanent shutdown.\n\nReport completion via standard channels.\n\nRewards: 850 EXP · 480 Currency · 240 CRD · 480 Reputation · Stabilizer Gyro Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 457)
