values ('dialog_fq_omni_045', 'fq_omni_045', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Behemoth Error Correction — Aethel Corrupted Behemoths are error cascades in the void system", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 3x Aethel Corrupted Behemoth; Collect 1x Confirm errors corrected.\n\nReport completion via standard channels.\n\nRewards: 2500 EXP · 1300 Currency · 650 CRD · 800 Reputation · Corrupted Synapse Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 473)
