values ('dialog_fq_omni_049', 'fq_omni_049', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The Shattered Heart is an unexploited resource sector", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Travel to SHATTERED_HEART; Collect 1x Complete sector analysis.\n\nReport completion via standard channels.\n\nRewards: 2500 EXP · 1300 Currency · 650 CRD · 800 Reputation · Con Elite Recovery Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 477)
